<template><ThemePage><view class="withdrawal-page" data-withdrawal-application>
 <view class="cash-header"><view class="cash-art"/><view class="cash-nav"><button class="back-arrow" aria-label="返回分销中心" @tap="back"/><text>提现</text></view><view class="cash-amount">{{ s.config?.withdrawable_amount ?? '—' }}</view><view class="cash-label">可提现金额</view></view>
 <view class="withdraw-wrapper">
  <view v-if="!s.loggedIn" class="form-body state"><view>登录后申请提现</view><button class="action" @tap="s.login">去登录</button></view>
  <template v-else>
   <view v-if="s.loading" class="form-body state" role="status">正在读取提现信息…</view>
   <template v-else-if="s.config || s.pending">
    <view v-if="s.pending" class="channel-tabs single"><text>待确认申请 · {{ channelName(s.pending.extract_type) }}</text></view>
    <view v-else-if="s.config?.channels.length" class="channel-tabs" :class="{single:s.config.channels.length===1}"><view v-if="tabArt" class="tab-art" :style="{backgroundImage:'url('+tabArt+')'}"/><button v-for="channel in s.config.channels" :key="channel" class="channel" :class="{selected:s.draft.extract_type===channel}" :disabled="s.locked" @tap="s.selectChannel(channel)">{{ s.config.channels.length===1?'提现至':'' }}{{ channelName(channel) }}</button></view>
    <view v-else class="form-body state">当前暂无可用提现方式</view>
    <view v-if="s.pending || s.config?.channels.length" :key="s.formEpoch" class="form-body">
     <view class="fields">
      <template v-if="s.draft.extract_type==='bank' || s.draft.extract_type==='alipay'"><view class="field"><text class="label">{{ s.draft.extract_type==='bank'?'持卡人':'姓名' }}</text><input v-model="s.draft.real_name" :disabled="s.locked" maxlength="128" :placeholder="s.draft.extract_type==='bank'?'请输入持卡人姓名':'请输入姓名'" aria-label="收款人姓名"/></view></template>
      <view v-if="s.draft.extract_type==='bank' || s.draft.extract_type==='alipay' || s.draft.extract_type==='weixin' && s.config?.wechat_mode!=='automatic'" class="field"><text class="label">{{ s.draft.extract_type==='bank'?'卡号':'账号' }}</text><input v-model="s.draft.extract_number" :disabled="s.locked" maxlength="128" :placeholder="s.draft.extract_type==='bank'?'请输入卡号':s.draft.extract_type==='alipay'?'请输入您的支付宝账号':'请输入您的微信账号'" aria-label="收款账号"/></view>
      <view v-if="s.draft.extract_type==='bank'" class="field"><text class="label">银行</text><picker :disabled="s.locked || !s.config?.banks.length" :range="s.config?.banks ?? []" :value="bankIndex" @change="s.chooseBank"><view class="bank-value" :class="{placeholder:!s.draft.bank_name}">{{ s.draft.bank_name || '请选择银行' }}<text class="right-arrow"/></view></picker></view>
      <view class="field amount-field"><text class="label">提现</text><input v-model="s.draft.extract_price" :disabled="s.locked" type="digit" maxlength="13" :placeholder="'最低提现金额：¥'+(s.config?.min_amount ?? '—')" aria-label="提现金额"/><button class="all-amount" :disabled="s.locked" @tap="s.all">全部提现</button></view>
      <view v-if="s.needsCode || s.draft.qrcode_url" class="field code-field"><text class="label">收款码</text><view><view v-if="s.image" class="code-preview"><image :key="s.image" :src="s.image" mode="aspectFit" @error="s.preview=''"/><button class="remove-code" :disabled="s.locked" aria-label="移除收款码" @tap="s.removeCode">×</button></view><button v-else class="upload-code" :disabled="s.locked" @tap="s.chooseCode"><view class="camera-icon"/><text>{{ s.draft.qrcode_url?'预览待读取':'上传图片' }}</text></button><button v-if="s.draft.qrcode_url && !s.image" class="media-refresh" :disabled="!!s.busy" @tap="s.refreshMedia">重新读取收款码</button></view></view>
     </view>
     <view v-if="s.config" class="hint">当前可提现金额: ￥{{ s.config.withdrawable_amount }}，冻结佣金：￥{{ s.config.frozen_amount }}</view>
     <view v-if="s.config && s.draft.extract_type!=='balance'" class="hint">提现手续费: <text>{{ s.config.fee_rate }}%</text>，预计到账: <text>￥{{ s.estimate?.net_amount ?? '—' }}</text></view>
     <view v-if="s.config?.freeze_days" class="hint">说明: 每笔佣金的冻结期为{{ s.config.freeze_days }}天，到期后可提现</view>
     <view v-if="s.config?.wechat_mode==='automatic' && s.draft.extract_type==='weixin'" class="hint">微信自动方式将登记申请，到账以实际后续状态为准。</view>
    </view>
   </template>
   <view v-if="s.pending" class="pending-note">上一笔申请结果待确认，收款信息已锁定。查询或重试使用同一申请标识。</view>
   <view v-if="s.notice" class="notice" role="status">{{ s.notice }}</view><view v-if="s.error" class="error" role="alert">{{ s.error }}</view>
   <button v-if="s.pending" class="secondary" :disabled="s.loading || !!s.busy" @tap="s.recover">查询原申请</button>
   <button v-if="s.pending || s.config?.channels.length" class="action" :disabled="s.loading || !!s.busy || !s.storageReady" @tap="s.submit">{{ s.busy==='upload'?'正在上传…':s.busy?'正在处理…':s.pending?'重试同一申请':'立即提现' }}</button>
   <button v-if="s.error && !s.pending" class="secondary" :disabled="s.loading || !!s.busy" @tap="s.load">重新读取提现信息</button><button class="secondary" @tap="records">查看提现记录</button>
  </template>
 </view>
 </view></ThemePage></template>
<script setup lang="ts">
import {computed,reactive} from 'vue';
import ThemePage from '@/components/ThemePage.vue';
import {useWithdrawalApplication} from '@/composables/useWithdrawalApplication';
import {withdrawalChannelName as channelName} from '@/api/withdrawalApplication';
const s=reactive(useWithdrawalApplication());
const bankIndex=computed(()=>Math.max(0,s.config?.banks.indexOf(s.draft.bank_name)??0));
const tabArt=computed(()=>{if(s.pending||!s.config)return '';const count=s.config.channels.length,index=s.config.channels.indexOf(s.draft.extract_type);if(count<2||index<0)return '';const numbers=count===4?[6,7,8,9]:count===3?[1,2,3]:[4,5];return '/static/php-withdrawal/tixian0'+numbers[index]+'.png';});
function back(){uni.redirectTo({url:'/pages/user/finance'});}function records(){if(s.loggedIn)uni.navigateTo({url:'/pages/user/distributionLedgers?type=4'});}
</script>
