de{position:absolute;right:0;top:0;width:32rpx;height:32rpx;line-height:30rpx;background:#999;color:white;border-radius:0 14rpx 0 8rpx;font-size:26rpx;padding:0;margin:0}.media-refresh{padding:10rpx 0;margin:6rpx 0;background:transparent;color:var(--view-theme,#e93323);font-size:24rpx;line-height:36rpx}.hint{font-size:24rpx;color:#999;line-height:38rpx;margin-top:16rpx;overflow-wrap:anywhere}.hint text{color:var(--view-theme,#e93323)}.action{width:100%;height:88rpx;line-height:88rpx;text-align:center;border-radius:50rpx;background:var(--view-theme,#e93323);color:#fff;font-size:28rpx;margin:48rpx auto 24rpx;padding:0}.action[disabled]{opacity:.55}.secondary{padding:8rpx 12rpx;background:transparent;color:#777;font-size:26rpx;line-height:44rpx;margin:12rpx auto}.state{text-align:center;padding:40rpx 24rpx;font-size:28rpx;line-height:44rpx;border-radius:24rpx}.notice,.pending-note,.error{margin:24rpx 10rpx;font-size:26rpx;line-height:42rpx;overflow-wrap:anywhere}.notice,.pending-note{color:#777}.error{color:#b34428}
